# 📄 PDF Builder Tool

Since I can't natively generate PDFs, I'll create an interactive web app where you can **build content and save/export it as a PDF** right in your browser!

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>PDF Builder</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }

        :root {
            --bg: #0f1117;
            --surface: #1a1d27;
            --border: #2a2d3a;
            --accent: #6c5ce7;
            --accent2: #a29bfe;
            --text: #e8e8f0;
            --muted: #6b6b80;
            --success: #00cec9;
            --danger: #ff6b6b;
        }

        body {
            font-family: 'Segoe UI', system-ui, sans-serif;
            background: var(--bg);
            color: var(--text);
            min-height: 100vh;
        }

        /* Header */
        .header {
            background: var(--surface);
            border-bottom: 1px solid var(--border);
            padding: 16px 32px;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .logo {
            display: flex;
            align-items: center;
            gap: 12px;
            font-size: 1.4rem;
            font-weight: 700;
        }

        .logo-icon {
            width: 36px; height: 36px;
            background: linear-gradient(135deg, var(--accent), var(--accent2));
            border-radius: 10px;
            display: grid;
            place-items: center;
            font-size: 1rem;
        }

        .btn {
            padding: 10px 20px;
            border: none;
            border-radius: 8px;
            cursor: pointer;
            font-size: 0.9rem;
            font-weight: 600;
            transition: all 0.2s;
            display: inline-flex;
            align-items: center;
            gap: 8px;
        }

        .btn-primary {
            background: linear-gradient(135deg, var(--accent), var(--accent2));
            color: white;
        }
        .btn-primary:hover { transform: translateY(-1px); box-shadow: 0 4px 20px rgba(108,92,231,0.4); }

        .btn-secondary {
            background: var(--border);
            color: var(--text);
        }
        .btn-secondary:hover { background: #3a3d4a; }

        .btn-success {
            background: linear-gradient(135deg, #00b894, var(--success));
            color: white;
        }
        .btn-success:hover { box-shadow: 0 4px 20px rgba(0,206,201,0.4); }

        .btn-danger {
            background: transparent;
            color: var(--danger);
            border: 1px solid var(--danger);
            padding: 6px 12px;
            font-size: 0.8rem;
        }
        .btn-danger:hover { background: rgba(255,107,107,0.1); }

        /* Layout */
        .layout {
            display: grid;
            grid-template-columns: 300px 1fr 340px;
            min-height: calc(100vh - 69px);
        }

        /* Sidebar - Components */
        .sidebar {
            background: var(--surface);
            border-right: 1px solid var(--border);
            padding: 20px;
            overflow-y: auto;
        }

        .sidebar h3 {
            font-size: 0.75rem;
            text-transform: uppercase;
            letter-spacing: 1.5px;
            color: var(--muted);
            margin-bottom: 12px;
        }

        .component-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 8px;
            margin-bottom: 24px;
        }

        .comp-btn {
            background: var(--bg);
            border: 1px solid var(--border);
            border-radius: 8px;
            padding: 16px 8px;
            color: var(--text);
            cursor: pointer;
            text-align: center;
            transition: all 0.2s;
            font-size: 0.8rem;
        }

        .comp-btn:hover {
            border-color: var(--accent);
            background: rgba(108,92,231,0.1);
        }

        .comp-btn .icon { font-size: 1.5rem; display: block; margin-bottom: 6px; }

        /* Canvas Area */
        .canvas-wrap {
            padding: 32px;
            overflow-y: auto;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 24px;
        }

        .page {
            width: 595px;
            min-height: 842px;
            background: white;
            color: #1a1a2e;
            border-radius: 4px;
            box-shadow: 0 4px 40px rgba(0,0,0,0.5);
            padding: 60px;
            position: relative;
            flex-shrink: 0;
        }

        .block {
            position: relative;
            margin-bottom: 12px;
            border: 2px solid transparent;
            border-radius: 6px;
            padding: 4px;
            transition: border-color 0.2s;
        }

        .block:hover { border-color: var(--accent2); }
        .block.selected { border-color: var(--accent); }

        .block-controls {
            display: none;
            position: absolute;
            top: -36px;
            right: 0;
            gap: 4px;
            background: var(--surface);
            padding: 4px;
            border-radius: 6px;
            z-index: 10;
        }

        .block.selected .block-controls { display: flex; }

        .block-ctrl-btn {
            background: transparent;
            border: none;
            color: var(--text);
            cursor: pointer;
            padding: 4px 6px;
            border-radius: 4px;
            font-size: 0.8rem;
        }
        .block-ctrl-btn:hover { background: var(--border); }

        .block-content {
            outline: none;
            min-height: 20px;
            cursor: text;
        }

        /* Block Types */
        .block-heading1 { font-size: 2rem; font-weight: 800; line-height: 1.3; }
        .block-heading2 { font-size: 1.5rem; font-weight: 700; line-height: 1.4; }
        .block-heading3 { font-size: 1.15rem; font-weight: 600; line-height: 1.5; }
        .block-paragraph { font-size: 1rem; line-height: 1.75; color: #333; }
        .block-hr { border-top: 2px solid #ddd; padding: 0; cursor: default; }
        .block-image { text-align: center; }
        .block-image img { max-width: 100%; border-radius: 6px; }
        .block-quote { border-left: 4px solid var(--accent); padding-left: 20px; font-style: italic; color: #555; font-size: 1.1rem; }
        .block-code { background: #1e1e2e; color: #cdd6f4; padding: 20px; border-radius: 8px; font-family: 'Fira Code', monospace; font-size: 0.85rem; line-height: 1.6; white-space: pre-wrap; }
        .block-table { width: 100%; border-collapse: collapse; }
        .block-table th, .block-table td { border: 1px solid #ddd; padding: 10px 14px; text-align: left; font-size: 0.9rem; }
        .block-table th { background: var(--accent); color: white; font-weight: 600; }

        /* Right Panel */
        .props-panel {
            background: var(--surface);
            border-left: 1px solid var(--border);
            padding: 20px;
            overflow-y: auto;
        }

        .prop-group {
            margin-bottom: 20px;
        }

        .prop-group label {
            display: block;
            font-size: 0.75rem;
            text-transform: uppercase;
            letter-spacing: 1px;
            color: var(--muted);
            margin-bottom: 8px;
        }

        .prop-input {
            width: 100%;
            background: var(--bg);
            border: 1px solid var(--border);
            border-radius: 6px;
            padding: 10px 12px;
            color: var(--text);
            font-size: 0.9rem;
            outline: none;
        }
        .prop-input:focus { border-color: var(--accent); }

        .prop-select {
            width: 100%;
            background: var(--bg);
            border: 1px solid var(--border);
            border-radius: 6px;
            padding: 10px 12px;
            color: var(--text);
            font-size: 0.9rem;
            outline: none;
            cursor: pointer;
        }

        .color-row {
            display: flex;
            gap: 8px;
            align-items: center;
        }

        .color-swatch {
            width: 36px; height: 36px;
            border-radius: 8px;
            border: 2px solid var(--border);
            cursor: pointer;
            padding: 0;
        }

        .color-swatch::-webkit-color-swatch-wrapper { padding: 0; }
        .color-swatch::-webkit-color-swatch { border: none; border-radius: 6px; }

        .toolbar-row {
            display: flex;
            gap: 4px;
            flex-wrap: wrap;
        }

        .tool-btn {
            background: var(--bg);
            border: 1px solid var(--border);
            border-radius: 6px;
            padding: 8px 10px;
            color: var(--text);
            cursor: pointer;
            font-size: 0.85rem;
            transition: all 0.15s;
        }
        .tool-btn:hover { border-color: var(--accent); background: rgba(108,92,231,0.15); }
        .tool-btn.active { border-color: var(--accent); background: rgba(108,92,231,0.2); }

        /* Page Settings */
        .page-settings {
            background: rgba(108,92,231,0.08);
            border: 1px solid rgba(108,92,231,0.3);
            border-radius: 10px;
            padding: 16px;
            margin-bottom: 20px;
        }

        .page-settings h3 {
            font-size: 0.9rem;
            margin-bottom: 12px;
            color: var(--accent2);
        }

        /* Print styles */
        @media print {
            body * { visibility: hidden; }
            .page, .page * { visibility: visible; }
            .page {
                position: absolute;
                left: 0; top: 0;
                box-shadow: none;
                border-radius: 0;
                margin: 0;
                width: 100%;
                padding: 40px;
            }
            .block { border: none !important; padding: 2px !important; }
            .block-controls { display: none !important; }
        }

        /* Empty state */
        .empty-state {
            text-align: center;
            padding: 60px 20px;
            color: #999;
        }
        .empty-state .icon { font-size: 3rem; margin-bottom: 12px; }
        .empty-state p { font-size: 0.9rem; }

        /* Divider in sidebar */
        .section-divider {
            border: none;
            border-top: 1px solid var(--border);
            margin: 16px 0;
        }

        /* Toast */
        .toast {
            position: fixed;
            bottom: 24px;
            left: 50%;
            transform: translateX(-50%) translateY(80px);
            background: var(--surface);
            border: 1px solid var(--success);
            color: var(--text);
            padding: 12px 24px;
            border-radius: 10px;
            font-size: 0.9rem;
            transition: transform 0.3s ease;
            z-index: 999;
        }
        .toast.show { transform: translateX(-50%) translateY(0); }

        @media (max-width: 1100px) {
            .layout { grid-template-columns: 1fr; }
            .sidebar, .props-panel { display: none; }
        }
    </style>
</head>
<body>

<div class="header">
    <div class="logo">
        <div class="logo-icon">📄</div>
        <span>PDF Builder</span>
    </div>
    <div style="display:flex; gap:10px;">
        <button class="btn btn-secondary" onclick="clearPage()">🗑️ Clear</button>
        <button class="btn btn-secondary" onclick="previewDoc()">👁️ Preview</button>
        <button class="btn btn-success" onclick="exportPDF()">⬇️ Save as PDF</button>
    </div>
</div>

<div class="layout">
    <!-- LEFT SIDEBAR -->
    <div class="sidebar">
        <h3>Add Elements</h3>
        <div class="component-grid">
            <button class="comp-btn" onclick="addBlock('heading1')">
                <span class="icon">H1</span>Title
            </button>
            <button class="comp-btn" onclick="addBlock('heading2')">
                <span class="icon">H2</span>Heading
            </button>
            <button class="comp-btn" onclick="addBlock('heading3')">
                <span class="icon">H3</span>Subheading
            </button>
            <button class="comp-btn" onclick="addBlock('paragraph')">
                <span class="icon">¶</span>Paragraph
            </button>
            <button class="comp-btn" onclick="addBlock('quote')">
                <span class="icon">❝</span>Quote
            </button>
            <button class="comp-btn" onclick="addBlock('code')">
                <span class="icon">{ }</span>Code
            </button>
            <button class="comp-btn" onclick="addBlock('hr')">
                <span class="icon">—</span>Divider
            </button>
            <button class="comp-btn" onclick="addBlock('table')">
                <span class="icon">⊞</span>Table
            </button>
            <button class="comp-btn" onclick="addBlock('image')">
                <span class="icon">🖼</span>Image
            </button>
            <button class="comp-btn" onclick="addBlock('pagebreak')">
                <span class="icon">⟐</span>Page Break
            </button>
        </div>

        <hr class="section-divider">

        <h3>Document Settings</h3>
        <div class="prop-group">
            <label>Page Size</label>
            <select class="prop-select" id="pageSize" onchange="setPageSize()">
                <option value="a4">A4 (210 × 297 mm)</option>
                <option value="letter">Letter (8.5 × 11 in)</option>
                <option value="legal">Legal (8.5 × 14 in)</option>
            </select>
        </div>
        <div class="prop-group">
            <label>Margins</label>
            <select class="prop-select" id="pageMargins" onchange="setMargins()">
                <option value="60">Default (60px)</option>
                <option value="40">Narrow (40px)</option>
                <option value="80">Wide (80px)</option>
            </select>
        </div>
        <div class="prop-group">
            <label>Background Color</label>
            <div class="color-row">
                <input type="color" class="color-swatch" id="bgColor" value="#ffffff" onchange="changeBg()">
                <span id="bgColorHex" style="font-size:0.85rem; color:var(--muted)">#ffffff</span>
            </div>
        </div>
    </div>

    <!-- CANVAS -->
    <div class="canvas-wrap">
        <div class="page" id="page">
            <div class="empty-state" id="emptyState">
                <div class="icon">📝</div>
                <p>Click elements from the panel<br>to start building your document</p>
            </div>
        </div>
    </div>

    <!-- RIGHT PANEL -->
    <div class="props-panel">
        <h3 style="font-size:0.75rem;text-transform:uppercase;letter-spacing:1.5px;color:var(--muted);margin-bottom:16px;">Properties</h3>
        <div id="propsContent">
            <p style="color:var(--muted);font-size:0.85rem;">Select a block to edit its properties</p>
        </div>
    </div>
</div>

<div class="toast" id="toast"></div>

<script>
    let blocks = [];
    let selectedId = null;

    const page = document.getElementById('page');
    const emptyState = document.getElementById('emptyState');
    const propsContent = document.getElementById('propsContent');

    function addBlock(type) {
        if (type === 'pagebreak') {
            const id = Date.now();
            const block = { id, type, content: '' };
            blocks.push(block);
            renderBlocks();
            selectBlock(id);
            return;
        }

        const id = Date.now() + Math.random();
        const defaults = getDefaults(type);
        const block = { id, type, ...defaults };
        blocks.push(block);
        renderBlocks();
        selectBlock(id);
    }

    function getDefaults(type) {
        switch(type) {
            case 'heading1': return { content: 'Document Title', align: 'left', fontSize: '', color: '' };
            case 'heading2': return { content: 'Section Heading', align: 'left', fontSize: '', color: '' };
            case 'heading3': return { content: 'Subsection', align: 'left', fontSize: '', color: '' };
            case 'paragraph': return { content: 'Start typing your content here. You can write multiple paragraphs and format your document as needed.', align: 'left', fontSize: '', color: '' };
            case 'quote': return { content: 'The only way to do great work is to love what you do.', align: 'left', fontSize: '', color: '' };
            case 'code': return { content: '// Write your code here\nfunction hello() {\n  return "world";\n}', align: 'left', fontSize: '', color: '' };
            case 'hr': return { align: 'center', fontSize: '', color: '' };
            case 'table': return { content: JSON.stringify({ headers: ['Column 1', 'Column 2', 'Column 3'], rows: [['Row 1', 'Data A', 'Data X'], ['Row 2', 'Data B', 'Data Y']] }), align: 'center', fontSize: '', color: '' };
            case 'image': return { src: '', align: 'center', alt: 'Image', width: '100%', fontSize: '', color: '' };
            default: return { content: '', align: 'left', fontSize: '', color: '' };
        }
    }

    function renderBlocks() {
        emptyState.style.display = blocks.length ? 'none' : 'block';

        // Remove all block elements but keep emptyState
        Array.from(page.querySelectorAll('.block, .pagebreak-line')).forEach(el => el.remove());

        blocks.forEach(block => {
            if (block.type === 'pagebreak') {
                const div = document.createElement('div');
                div.className = 'pagebreak-line';
                div.innerHTML = '<div style="text-align:center;color:#aaa;font-size:0.8rem;padding:20px 0;border-top:2px dashed #ccc;border-bottom:2px dashed #ccc;margin:20px 0;">⟐ &nbsp;Page Break&nbsp; ⟐</div>';
                div.dataset.id = block.id;
                div.onclick = (e) => { e.stopPropagation(); selectBlock(block.id); };
                page.appendChild(div);
                return;
            }

            const div = document.createElement('div');
            div.className = `block ${block.type} ${selectedId == block.id ? 'selected' : ''}`;
            div.dataset.id = block.id;

            const ctrl = document.createElement('div');
            ctrl.className = 'block-controls';
            ctrl.innerHTML = `
                <button class="block-ctrl-btn" onclick="moveBlock('${block.id}',-1)" title="Move Up">↑</button>
                <button class="block-ctrl-btn" onclick="moveBlock('${block.id}',1)" title="Move Down">↓</button>
                <button class="block-ctrl-btn" onclick="duplicateBlock('${block.id}')" title="Duplicate">⧉</button>
                <button class="block-ctrl-btn" onclick="removeBlock('${block.id}')" title="Delete" style="color:#ff6b6b">✕</button>
            `;
            div.appendChild(ctrl);

            const content = document.createElement('div');
            content.className = 'block-content';
            content.contentEditable = true;
            content.classList.add(`block-${block.type}`);

            if (block.type === 'table') {
                content.innerHTML = renderTable(block.content);
                content.onclick = (e) => { if(e.target === content) selectBlock(block.id); };
            } else if (block.type === 'image') {
                if (block.src) {
                    content.innerHTML = `<img src="${block.src}" alt="${block.alt || ''}" style="max-width:${block.width};border-radius:6px;">`;
                } else {
                    content.innerHTML = `<div style="padding:30px;border:2px dashed #ccc;border-radius:8px;color:#999;text-align:center;">🖼️ Image placeholder<br><small>Paste image URL in properties</small></div>`;
                }
                content.onclick = (e) => { if(e.target === content || e.target.tagName==='IMG') selectBlock(block.id); };
            } else if (block.type === 'hr') {
                content.innerHTML = '';
                content.contentEditable = false;
            } else {
                content.textContent = block.content;
                content.addEventListener('input', () => {
                    const b = blocks.find(b => b.id == block.id);
                    if (b) b.content = content.textContent;
                });
            }

            // Apply alignment and colors
            if (block.align) content.style.textAlign = block.align;
            if (block.color) content.style.color = block.color;
            if (block.fontSize) content.style.fontSize = block.fontSize;

            div.appendChild(content);
            div.onclick = (e) => { e.stopPropagation(); selectBlock(block.id); };
            page.appendChild(div);
        });
    }

    function renderTable(json) {
        try {
            const t = JSON.parse(json);
            let html = '<table class="block-table"><thead><tr>';
            t.headers.forEach(h => html += `<th>${h}</th>`);
            html += '</tr></thead><tbody>';
            t.rows.forEach(row => {
                html += '<tr>';
                row.forEach(cell => html += `<td>${cell}</td>`);
                html += '</tr>';
            });
            html += '</tbody></table>';
            return html;
        } catch { return '<p style="color:red;">Invalid table data</p>'; }
    }

    function selectBlock(id) {
        selectedId = id;
        document.querySelectorAll('.block').forEach(el => el.classList.remove('selected'));
        const el = page.querySelector(`.block[data-id="${id}"]`);
        if (el) el.classList.add('selected');
        showProps(id);
    }

    function showProps(id) {
        const block = blocks.find(b => b.id == id);
        if (!block) { propsContent.innerHTML = '<p style="color:var(--muted);font-size:0.85rem;">Select a block</p>'; return; }

        let html = `
            <div class="prop-group">
                <label>Type</label>
                <div style="background:var(--bg);padding:10px;border-radius:6px;font-size:0.9rem;color:var(--accent2);">${block.type.charAt(0).toUpperCase() + block.type.slice(1)}</div>
            </div>
            <div class="prop-group">
                <label>Alignment</label>
                <div class="toolbar-row">
                    <button class="tool-btn ${block.align==='left'?'active':''}" onclick="setProp(${id},'align','left')">◧ Left</button>
                    <button class="tool-btn ${block.align==='center'?'active':''}" onclick="setProp(${id},'align','center')">◫ Center</button>
                    <button class="tool-btn ${block.align==='right'?'active':''}" onclick="setProp(${id},'align','right')">◨ Right</button>
                </div>
            </div>
            <div class="prop-group">
                <label>Font Size</label>
                <select class="prop-select" onchange="setProp(${id},'fontSize',this.value)">
                    <option value="" ${!block.fontSize?'selected':''}>Default</option>
                    <option value="0.8rem" ${block.fontSize==='0.8rem'?'selected':''}>Small</option>
                    <option value="0.9rem" ${block.fontSize==='0.9rem'?'selected':''}>Normal</option>
                    <option value="1.1rem" ${block.fontSize==='1.1rem'?'selected':''}>Large</option>
                    <option value="1.3rem" ${block.fontSize==='1.3rem'?'selected':''}>Extra Large</option>
                </select>
            </div>
            <div class="prop-group">
                <label>Text Color</label>
                <div class="color-row">
                    <input type="color" class="color-swatch" value="${block.color || '#333333'}" onchange="setProp(${id},'color',this.value)">
                    <span style="font-size:0.85rem;color:var(--muted);">${block.color || '#333333'}</span>
                </div>
            </div>
        `;

        if (block.type === 'image') {
            html += `
                <hr class="section-divider">
                <div class="prop-group">
                    <label>Image URL</label>
                    <input class="prop-input" type="text" placeholder="https://..." value="${block.src || ''}" oninput="setImageSrc(${id}, this.value)">
                </div>
                <div class="prop-group">
                    <label>Width</label>
                    <select class="prop-select" onchange="setProp(${id},'width',this.value)">
                        <option value="100%" ${block.width==='100%'?'selected':''}>Full Width</option>
                        <option value="75%" ${block.width==='75%'?'selected':''}>75%</option>
                        <option value="50%" ${block.width==='50%'?'selected':''}>50%</option>
                        <option value="300px" ${block.width==='300px'?'selected':''}>300px</option>
                    </select>
                </div>
            `;
        }

        if (block.type === 'table') {
            html += `
                <hr class="section-divider">
                <div class="prop-group">
                    <label>Header Text (comma-separated)</label>
                    <input class="prop-input" type="text" placeholder="Col1, Col2, Col3" 
                        value="${JSON.parse(block.content)?.headers?.join(', ') || ''}" 
                        oninput="editTableHeaders(this.value, ${id})">
                </div>
                <div class="prop-group">
                    <button class="btn btn-secondary" style="width:100%" onclick="editTableRow(${id}, 'add')">+ Add Row</button>
                </div>
                <div class="prop-group">
                    <button class="btn btn-danger" style="width:100%" onclick="editTableRow(${id}, 'remove')">− Remove Last Row</button>
                </div>
            `;
        }

        propsContent.innerHTML = html;
    }

    function setProp(id, prop, value) {
        const block = blocks.find(b => b.id == id);
        if (block) { block[prop] = value; renderBlocks(); selectBlock(id); }
    }

    function setImageSrc(id, src) {
        const block = blocks.find(b => b.id == id);
        if (block) { block.src = src; renderBlocks(); selectBlock(id); }
    }

    function editTableHeaders(val, id) {
        const block = blocks.find(b => b.id == id);
        if (!block) return;
        const data = JSON.parse(block.content);
        data.headers = val.split(',').map(s => s.trim());
        block.content = JSON.stringify(data);
    }

    function editTableRow(id, action) {
        const block = blocks.find(b => b.id == id);
        if (!block) return;
        const data = JSON.parse(block.content);
        if (action === 'add') {
            const cols = data.headers.length || 3;
            data.rows.push(Array(cols).fill('New'));
        } else if (action === 'remove' && data.rows.length) {
            data.rows.pop();
        }
        block.content = JSON.stringify(data);
        renderBlocks();
        selectBlock(id);
    }

    function moveBlock(id, dir) {
        const idx = blocks.findIndex(b => b.id == id);
        const newIdx = idx + dir;
        if (newIdx < 0 || newIdx >= blocks.length) return;
        [blocks[idx], blocks[newIdx]] = [blocks[newIdx], blocks[idx]];
        renderBlocks();
        selectBlock(id);
    }

    function duplicateBlock(id) {
        const idx = blocks.findIndex(b => b.id == id);
        const copy = { ...blocks[idx], id: Date.now() + Math.random() };
        blocks.splice(idx + 1, 0, copy);
        renderBlocks();
        selectBlock(copy.id);
    }

    function removeBlock(id) {
        blocks = blocks.filter(b => b.id != id);
        if (selectedId == id) { selectedId = null; propsContent.innerHTML = '<p style="color:var(--muted);font-size:0.85rem;">Select a block</p>'; }
        renderBlocks();
    }

    function clearPage() {
        if (!confirm('Clear all content?')) return;
        blocks = [];
        selectedId = null;
        renderBlocks();
        propsContent.innerHTML = '<p style="color:var(--muted);font-size:0.85rem;">Select a block</p>';
    }

    function setPageSize() {
        const ps = document.getElementById('pageSize').value;
        const p = page;
        if (ps === 'a4') { p.style.width = '595px'; p.style.minHeight = '842px'; }
        else if (ps === 'letter') { p.style.width = '612px'; p.style.minHeight = '792px'; }
        else { p.style.width = '612px'; p.style.minHeight = '1008px'; }
    }

    function setMargins() {
        const m = document.getElementById('pageMargins').value;
        page.style.padding = m + 'px';
    }

    function changeBg() {
        const c = document.getElementById('bgColor').value;
        page.style.background = c;
        document.getElementById('bgColorHex').textContent = c;
    }

    function previewDoc() {
        window.print();
    }

    function exportPDF() {
        showToast('Opening print dialog — choose "Save as PDF" to export!');
        setTimeout(() => window.print(), 300);
    }

    function showToast(msg) {
        const t = document.getElementById('toast');
        t.textContent = msg;
        t.classList.add('show');
        setTimeout(() => t.classList.remove('show'), 3000);
    }

    // Click canvas background to deselect
    page.addEventListener('click', (e) => {
        if (e.target === page) { selectedId = null; propsContent.innerHTML = '<p style="color:var(--muted);font-size:0.85rem;">Select a block to edit</p>'; }
    });

    renderBlocks();
</script>

</body>
</html>
```

## How It Works

1. **Add elements** from the left sidebar — titles, headings, paragraphs, quotes, code blocks, tables, images, etc.
2. **Click any block** to select it, then edit its properties (alignment, font size, color) in the right panel
3. **Drag blocks up/down** with the arrow buttons that appear on hover
4. **Duplicate or delete** blocks with the control buttons
5. When you're done, click **"Save as PDF"** → it opens your browser's print dialog
6. Choose **"Save as PDF"** as the destination to download!

